INSERT OR IGNORE INTO events (id, slug, era_id, order_index, hijri_year, gregorian_approx, prophet_age, place_id, route_id, certainty, status, needs_verification, published_at) VALUES ('seed-event-year-of-the-elephant', 'year-of-the-elephant', 'seed-era-pre-islamic-arabia', 1024, -53, 570, NULL, 'seed-place-makkah', 'seed-route-elephant', 'agreed', 'draft', 1, NULL);
INSERT OR IGNORE INTO event_translations (event_id, lang, title, summary, key_details, lessons, dispute_note, status) VALUES ('seed-event-year-of-the-elephant', 'bn', 'হস্তীবাহিনীর বছর', 'ইয়েমেনের শাসক আবরাহা কাবা ধ্বংস করার উদ্দেশ্যে হাতিসহ বিশাল এক বাহিনী নিয়ে মক্কার দিকে অগ্রসর হয়। মক্কার উপকণ্ঠে পৌঁছালে আল্লাহ ঝাঁকে ঝাঁকে পাখি পাঠান; তারা পোড়ামাটির কঙ্কর নিক্ষেপ করে এবং বাহিনীটি ধ্বংস হয়ে যায়। আরবরা এই বছরকে "আমুল ফীল" নামে স্মরণ করত, আর এ বছরেই নবীজি ﷺ জন্মগ্রহণ করেন।', '["আবরাহা সানআয় একটি বিশাল গির্জা নির্মাণ করে আরবদের হজ সেদিকে ফিরিয়ে নিতে চেয়েছিল।","মক্কার নেতা আবদুল মুত্তালিব আবরাহার কাছে শুধু নিজের উট ফেরত চান এবং বলেন, এই ঘরের একজন রব আছেন, তিনিই একে রক্ষা করবেন।","মক্কাবাসী আশপাশের পাহাড়ে আশ্রয় নেয়; কাবা রক্ষা পায় আল্লাহর সরাসরি হস্তক্ষেপে।"]', '["আল্লাহর ঘরের হেফাজতকারী আল্লাহ নিজেই।","শক্তি ও সংখ্যার অহংকার আল্লাহর ইচ্ছার সামনে টেকে না।","নবুয়তের আগেই আল্লাহ মক্কার মর্যাদা স্পষ্ট করে দেন।"]', NULL, 'draft');
