INSERT OR IGNORE INTO ayah_translations (ayah_id, lang, text, translation_source, translation_license) VALUES ('105:1', 'bn', 'আপনি কি দেখেননি আপনার পালনকর্তা হস্তীবাহিনীর সাথে কিরূপ ব্যবহার করেছেন?', 'tanzil-bn.bengali', 'UNVERIFIED: translation copyright is held by the translator/publisher; Tanzil distributes it for display with attribution. Owner must verify before commercial/public use.');
