INSERT OR IGNORE INTO recall_question_translations (question_id, lang, question, answer, distractors) VALUES ('seed-q-year-of-the-elephant-0', 'bn', 'হস্তীবাহিনীর শেষ পরিণতি কী হয়েছিল?', 'পাখির নিক্ষিপ্ত কঙ্করে ধ্বংস হয়', '["কাবা ক্ষতিগ্রস্ত করে ফিরে যায়","মক্কাবাসীর সাথে সন্ধি করে","নিরাপদে ইয়েমেনে ফিরে যায়"]');
