INSERT OR IGNORE INTO event_translations (event_id, lang, title, summary, key_details, lessons, dispute_note, status) VALUES ('seed-event-birth-of-the-prophet', 'bn', 'নবীজির ﷺ জন্ম', 'হস্তীবাহিনীর বছরে, রবিউল আউয়াল মাসের এক সোমবার মক্কায় বনু হাশিম গোত্রে নবীজি ﷺ জন্মগ্রহণ করেন। তাঁর মা আমিনা, আর দাদা আবদুল মুত্তালিব তাঁর নাম রাখেন মুহাম্মাদ ﷺ।', '["পিতা আবদুল্লাহ তাঁর জন্মের আগেই ইন্তেকাল করেন; দাদা আবদুল মুত্তালিব তাঁর অভিভাবক হন।","সোমবারে রোজা রাখা প্রসঙ্গে নবীজি ﷺ বলেছেন, এ দিনেই তাঁর জন্ম হয়েছে (সহীহ মুসলিম)।","আরব রীতি অনুযায়ী শিগগিরই তাঁকে দুধমায়ের কাছে মরুভূমিতে পাঠানোর প্রস্তুতি নেওয়া হয়।"]', '["আল্লাহ তাঁর রাসূলকে ﷺ ইয়াতীম অবস্থায় বড় করেছেন; তিনিই ছিলেন তাঁর প্রকৃত অভিভাবক।","বংশমর্যাদা ও পরিবেশ, দুটোই নবুয়তের দায়িত্বের জন্য প্রস্তুত ছিল।"]', 'রবিউল আউয়াল মাসের এক সোমবার জন্ম, এ বিষয়ে সবাই একমত। তারিখ নিয়ে মতভেদ আছে: প্রসিদ্ধ মত ১২ রবিউল আউয়াল, আর আর-রাহীকুল মাখতূমে ৯ রবিউল আউয়াল উল্লেখ করা হয়েছে।', 'draft');
