INSERT OR IGNORE INTO event_translations (event_id, lang, title, summary, key_details, lessons, dispute_note, status) VALUES ('seed-event-first-revelation-in-hira', 'bn', 'হেরা গুহায় প্রথম ওহী', 'নবুয়তের আগের বছরগুলোতে নবীজি ﷺ মক্কার কাছে জাবালে নূরের হেরা গুহায় নির্জনে ইবাদতে সময় কাটাতেন। চল্লিশ বছর বয়সে রমজান মাসে সেখানেই প্রথম ওহী নাযিল হয়: সূরা আল-আলাকের প্রথম পাঁচটি আয়াত। এর মধ্য দিয়েই নবুয়তের সূচনা হয়।', '["জিবরাঈল (আ.) এসে বলেন \"পড়ুন\"; নবীজি ﷺ উত্তর দেন, \"আমি পড়তে জানি না।\"","ঘরে ফিরে তিনি খাদিজা (রা.)-কে বলেন, \"আমাকে চাদর দিয়ে ঢেকে দাও।\" খাদিজা (রা.) তাঁকে সান্ত্বনা দেন এবং তাঁর উত্তম চরিত্রের কথা স্মরণ করিয়ে দেন।","খাদিজা (রা.) তাঁকে নিয়ে যান চাচাতো ভাই ওয়ারাকা ইবনে নাওফালের কাছে, যিনি একে নবুয়তের সূচনা বলে চিনতে পারেন।"]', '["ইসলামের প্রথম আদেশটিই ছিল পড়া ও জ্ঞান অর্জনের।","কঠিন মুহূর্তে জীবনসঙ্গীর আস্থা ও সান্ত্বনা অমূল্য।","নির্জনে চিন্তা ও ইবাদত বড় দায়িত্বের জন্য হৃদয়কে প্রস্তুত করে।"]', NULL, 'draft');
