INSERT OR IGNORE INTO ayah_translations (ayah_id, lang, text, translation_source, translation_license) VALUES ('96:1', 'bn', 'পাঠ করুন আপনার পালনকর্তার নামে যিনি সৃষ্টি করেছেন', 'tanzil-bn.bengali', 'UNVERIFIED: translation copyright is held by the translator/publisher; Tanzil distributes it for display with attribution. Owner must verify before commercial/public use.');
