INSERT OR IGNORE INTO event_translations (event_id, lang, title, summary, key_details, lessons, dispute_note, status) VALUES ('seed-event-hijrah-to-madinah', 'bn', 'হিজরত, মক্কা থেকে মদিনা', 'কুরাইশরা নবীজিকে ﷺ হত্যার ষড়যন্ত্র করলে আল্লাহর নির্দেশে তিনি আবু বকর (রা.)-কে সঙ্গে নিয়ে রাতের অন্ধকারে মক্কা ত্যাগ করেন। তাঁরা তিন রাত সাওর গুহায় আত্মগোপন করেন, তারপর প্রচলিত পথ এড়িয়ে উপকূলের দিক দিয়ে মদিনার পথে যাত্রা করেন। কুবায় কয়েক দিন অবস্থানের পর তিনি মদিনায় প্রবেশ করেন; পরে এই ঘটনা থেকেই হিজরি সনের গণনা শুরু হয়।', '["যে রাতে ঘাতকেরা ঘর ঘিরে রেখেছিল, আলী (রা.) নবীজির ﷺ বিছানায় শুয়ে থাকেন এবং পরে মানুষের গচ্ছিত আমানত ফেরত দেন।","সাওর গুহায় তিন রাত: আবদুল্লাহ ইবনে আবু বকর মক্কার খবর আনতেন, আর আসমা বিনতে আবু বকর (রা.) খাবার পৌঁছে দিতেন।","পথপ্রদর্শক আবদুল্লাহ ইবনে উরাইকিত তাঁদের অপ্রচলিত উপকূলীয় পথে নিয়ে যান।","কুবায় পৌঁছে নবীজি ﷺ মসজিদে কুবার ভিত্তি স্থাপন করেন, যা ইসলামের প্রথম মসজিদ।"]', '["আল্লাহর ওপর ভরসা আর সতর্ক পরিকল্পনা একসাথে চলে।","শত্রুর গচ্ছিত আমানতও ফেরত দেওয়া ঈমানের দাবি।","দ্বীনের জন্য পুরো পরিবার যার যার সামর্থ্যে অংশ নিয়েছিল।"]', NULL, 'draft');
INSERT OR IGNORE INTO ayat (id, surah, ayah, arabic_text, arabic_source) VALUES ('9:40', 9, 40, 'إِلَّا تَنصُرُوهُ فَقَدْ نَصَرَهُ ٱللَّهُ إِذْ أَخْرَجَهُ ٱلَّذِينَ كَفَرُوا۟ ثَانِىَ ٱثْنَيْنِ إِذْ هُمَا فِى ٱلْغَارِ إِذْ يَقُولُ لِصَٰحِبِهِۦ لَا تَحْزَنْ إِنَّ ٱللَّهَ مَعَنَا فَأَنزَلَ ٱللَّهُ سَكِينَتَهُۥ عَلَيْهِ وَأَيَّدَهُۥ بِجُنُودٍ لَّمْ تَرَوْهَا وَجَعَلَ كَلِمَةَ ٱلَّذِينَ كَفَرُوا۟ ٱلسُّفْلَىٰ وَكَلِمَةُ ٱللَّهِ هِىَ ٱلْعُلْيَا وَٱللَّهُ عَزِيزٌ حَكِيمٌ', 'tanzil-uthmani-1.1');
INSERT OR IGNORE INTO ayah_translations (ayah_id, lang, text, translation_source, translation_license) VALUES ('9:40', 'bn', 'যদি তোমরা তাকে (রসূলকে) সাহায্য না কর, তবে মনে রেখো, আল্লাহ তার সাহায্য করেছিলেন, যখন তাকে কাফেররা বহিষ্কার করেছিল, তিনি ছিলেন দু’জনের একজন, যখন তারা গুহার মধ্যে ছিলেন। তখন তিনি আপন সঙ্গীকে বললেন বিষন্ন হয়ো না, আল্লাহ আমাদের সাথে আছেন। অতঃপর আল্লাহ তার প্রতি স্বীয় সান্তনা নাযিল করলেন এবং তাঁর সাহায্যে এমন বাহিনী পাঠালেন, যা তোমরা দেখনি। বস্তুতঃ আল্লাহ কাফেরদের মাথা নীচু করে দিলেন আর আল্লাহর কথাই সদা সমুন্নত এবং আল্লাহ পরাক্রমশালী, প্রজ্ঞাময়।', 'tanzil-bn.bengali', 'UNVERIFIED: translation copyright is held by the translator/publisher; Tanzil distributes it for display with attribution. Owner must verify before commercial/public use.');
INSERT OR IGNORE INTO event_ayat (event_id, ayah_id, order_index) VALUES ('seed-event-hijrah-to-madinah', '9:40', 0);
