INSERT OR IGNORE INTO event_translations (event_id, lang, title, summary, key_details, lessons, dispute_note, status) VALUES ('seed-event-battle-of-badr', 'bn', 'বদরের যুদ্ধ', 'রমজান মাসে বদর প্রান্তরে প্রায় ৩১৩ জন মুসলিম তিন গুণের বেশি সংখ্যক কুরাইশ বাহিনীর মুখোমুখি হন। আল্লাহর সাহায্যে মুসলিমরা বিজয়ী হন; কুরআনে এই দিনকে "ইয়াওমুল ফুরকান" বলা হয়েছে।', '[]', '[]', NULL, 'draft');
